  function workLink(w,label){return `<button type="button" class="major-work-link ${esc(w.due_status||'')}" data-work-task="${esc(w.task_id)}" data-work-stage="${esc(w.stage_id||'')}" data-work-id="${esc(w.id||'')}">${label}</button>`}
