      <div class="major-work-assignee"><span class="form-label">담당자${editable&&w.ball_type!=='buyer'?' · 복수선택':''}</span>${!editable?`<span>${esc(w.assignee_name||'미지정')}</span>`:w.ball_type==='buyer'?(contacts.length?`<select name="contact_id" aria-label="거래처 담당자"><option value="">미지정</option>${contacts.map(c=>`<option value="${esc(c.id)}" ${w.contact_id===c.id?'selected':''}>${esc(c.contact_name)}</option>`).join('')}${w.contact_id&&!contacts.some(c=>c.id===w.contact_id)?`<option value="${esc(w.contact_id)}" selected>${esc(w.assignee_name||'기존 담당자')} · 기존</option>`:''}</select>`:`<input name="counterparty_name" maxlength="200" value="${esc(w.counterparty_name||w.assignee_name||'')}" placeholder="상대측 담당자명" aria-label="상대측 담당자명">`):'<div class="major-people-picker" data-work-person></div>'}</div>
