    const canEdit=Boolean(t.permissions?.structure&&!['completed','cancelled'].includes(t.status)&&!t.archived_at),items=(t.stage_work_items||[]).filter(w=>w.stage_id===stage.id);
    const visible=items.filter(w=>w.status!=='cancelled'&&(!workState.hideCompleted||w.status!=='completed')).sort((a,b)=>b.created_at.localeCompare(a.created_at)||b.id.localeCompare(a.id));
